#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 5);
const float temperatureLimitC = 8.0f;
unsigned long temperatureEvents = 0, openingEvents = 0, vibrationEvents = 0;
bool wasHot = false, wasOpen = false, wasShaking = false;
bool rawDoor = false, stableDoor = false;
unsigned long doorChangedAt = 0, lastRxAt = 0;
char positionText[96] = "unknown";
char rx[96];
unsigned int rxLength = 0;

void finishPosition() {
  if (!rxLength) return;
  rx[rxLength] = '\0';
  strncpy(positionText, rx, sizeof(positionText) - 1);
  positionText[sizeof(positionText) - 1] = '\0';
  rxLength = 0;
}

void readPosition(unsigned long now) {
  while (Serial.available()) {
    char c = (char)Serial.read();
    lastRxAt = now;
    if (c == '\n' || c == '\r') finishPosition();
    else if (rxLength < sizeof(rx) - 1) rx[rxLength++] = c;
  }
  if (rxLength && now - lastRxAt >= 20) finishPosition();
}

void logEvent(const char *event, float temperature) {
  Serial.print(event);
  Serial.print(" temperature=");
  Serial.print(temperature, 1);
  Serial.print(" position=");
  Serial.println(positionText);
}

void setup() {
  Serial.begin(9600);
  pinMode(A1, INPUT);
  pinMode(2, INPUT_PULLUP);
  pinMode(3, INPUT_PULLUP);
  pinMode(6, OUTPUT);
  pinMode(13, OUTPUT);
  digitalWrite(13, LOW);
  display.setBrightness(7);
  display.clear();
}

void loop() {
  unsigned long now = millis();
  readPosition(now);
  float temperature = analogRead(A1) * (500.0f / 1023.0f);
  bool hot = temperature > temperatureLimitC;
  bool door = digitalRead(3) == LOW;
  if (door != rawDoor) {
    rawDoor = door;
    doorChangedAt = now;
  }
  if (now - doorChangedAt >= 30) stableDoor = rawDoor;
  bool shaking = digitalRead(2) == LOW;
  if (hot && !wasHot) {
    ++temperatureEvents;
    logEvent("TEMPERATURE", temperature);
  }
  if (stableDoor && !wasOpen) {
    ++openingEvents;
    logEvent("OPEN", temperature);
  }
  if (shaking && !wasShaking) ++vibrationEvents;
  wasHot = hot;
  wasOpen = stableDoor;
  wasShaking = shaking;
  bool alarm = hot || stableDoor;
  digitalWrite(13, alarm ? HIGH : LOW);
  if (alarm) tone(6, 2000);
  else noTone(6);
  unsigned int page = (now / 2000UL) % 4;
  long value = page == 0 ? (long)(temperature + 0.5f) :
               page == 1 ? temperatureEvents :
               page == 2 ? openingEvents : vibrationEvents;
  if (value > 9999) value = 9999;
  display.showNumberDec((int)value, false);
  delay(5);
}
